import{_ as a,o as s,c as n,a2 as i}from"./chunks/framework.ClgMjOt7.js";const h=JSON.parse('{"title":"アーキテクチャ構成 & データフロー","description":"Palleria のレイヤー構造、クラス分類、ViewModel / Repository パターン","frontmatter":{"title":"アーキテクチャ構成 & データフロー","description":"Palleria のレイヤー構造、クラス分類、ViewModel / Repository パターン"},"headers":[],"relativePath":"architecture/index.md","filePath":"architecture/index.md","lastUpdated":1786169627000}'),o={name:"architecture/index.md"};function t(l,e,r,d,c,p){return s(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="アーキテクチャ構成-データフロー" tabindex="-1">アーキテクチャ構成 &amp; データフロー <a class="header-anchor" href="#アーキテクチャ構成-データフロー" aria-label="Permalink to &quot;アーキテクチャ構成 &amp; データフロー&quot;">​</a></h1><p>Palleria は、関心事の分離（Separation of Concerns）に基づいたマルチレイヤー構造を採用しています。</p><hr><h2 id="全体コンポーネントマップ" tabindex="-1">全体コンポーネントマップ <a class="header-anchor" href="#全体コンポーネントマップ" aria-label="Permalink to &quot;全体コンポーネントマップ&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  [ UI Layer (Compose Screens) ]</span></span>\n<span class="line"><span>    │   ▲</span></span>\n<span class="line"><span>    │   │  (StateFlow / UiState)</span></span>\n<span class="line"><span>    ▼   │</span></span>\n<span class="line"><span>  [ ViewModel Layer (IllustiaViewModelCore) ]</span></span>\n<span class="line"><span>    │   ▲</span></span>\n<span class="line"><span>    │   │  (Domain Models: Illust, UserProfile, etc.)</span></span>\n<span class="line"><span>    ▼   │</span></span>\n<span class="line"><span>  [ Repository Layer (IllustiaRepository / ManagedDataRepository) ]</span></span>\n<span class="line"><span>    ├───&gt; [ Local Storage (Room DB &amp; DataStore) ]</span></span>\n<span class="line"><span>    │</span></span>\n<span class="line"><span>    └───&gt; [ Native Bridge Layer (com.yunfie.illustia.rust) ]</span></span>\n<span class="line"><span>            │ (JNI Call)</span></span>\n<span class="line"><span>            ▼</span></span>\n<span class="line"><span>          [ Rust Core (pixiv-api) ] ──( HTTP )──&gt; [ Pixiv API Server ]</span></span></code></pre></div><hr><h2 id="レイヤー別役割定義" tabindex="-1">レイヤー別役割定義 <a class="header-anchor" href="#レイヤー別役割定義" aria-label="Permalink to &quot;レイヤー別役割定義&quot;">​</a></h2><h3 id="_1-ui-レイヤー-ui-screens-ui-components" tabindex="-1">1. UI レイヤー (<code>ui/screens/</code> &amp; <code>ui/components/</code>) <a class="header-anchor" href="#_1-ui-レイヤー-ui-screens-ui-components" aria-label="Permalink to &quot;1. UI レイヤー (`ui/screens/` &amp; `ui/components/`)&quot;">​</a></h3><ul><li><strong>Jetpack Compose + Miuix KMP</strong>: 宣言型 UI コンポーネントで構成。</li><li>単一方向データフロー（Unidirectional Data Flow）を遵守し、状態は <code>StateFlow</code> 経由で受信、ユーザーアクションは ViewModel のメソッド呼び出しとして送信。</li></ul><h3 id="_2-viewmodel-レイヤー-viewmodel" tabindex="-1">2. ViewModel レイヤー (<code>viewmodel/</code>) <a class="header-anchor" href="#_2-viewmodel-レイヤー-viewmodel" aria-label="Permalink to &quot;2. ViewModel レイヤー (`viewmodel/`)&quot;">​</a></h3><ul><li><strong><code>IllustiaViewModelCore</code></strong>: アプリの中心的な状態保持クラス。<code>UiState</code> を生成し、画面ごとのローディング、エラー、データ一覧状態を一元管理。</li><li><strong><code>ViewModelSnapshots</code></strong>: 画面遷移時のスクロール位置や検索条件のスナップショットを保持。</li></ul><h3 id="_3-リポジトリ-データレイヤー-data" tabindex="-1">3. リポジトリ &amp; データレイヤー (<code>data/</code>) <a class="header-anchor" href="#_3-リポジトリ-データレイヤー-data" aria-label="Permalink to &quot;3. リポジトリ &amp; データレイヤー (`data/`)&quot;">​</a></h3><ul><li><strong><code>IllustiaRepository</code></strong>: ネットワークデータとローカルキャッシュを仲介するリポジトリ。</li><li><strong><code>ManagedDataRepository</code></strong>: 設定情報およびダウンロードキューの永続化状態を管理。</li><li><strong><code>PixivApiClient</code> / <code>RustPixivHttpClient</code></strong>: Rust ネイティブ層の API インターフェースのラッパー。</li></ul><h3 id="_4-ネイティブブリッジレイヤー-nativebridge-rust" tabindex="-1">4. ネイティブブリッジレイヤー (<code>nativebridge/</code> / <code>rust/</code>) <a class="header-anchor" href="#_4-ネイティブブリッジレイヤー-nativebridge-rust" aria-label="Permalink to &quot;4. ネイティブブリッジレイヤー (`nativebridge/` / `rust/`)&quot;">​</a></h3><ul><li>UniFFI により生成された Kotlin バインディングコード (<code>PixivHttpClient</code>, <code>ApiException</code>)。</li><li>Java Native Interface (JNI) を介して、C ABI 互換の共有ライブラリ (<code>.so</code>) を安全に実行。</li></ul><h3 id="_5-ストレージレイヤー-settings-db" tabindex="-1">5. ストレージレイヤー (<code>settings/db/</code>) <a class="header-anchor" href="#_5-ストレージレイヤー-settings-db" aria-label="Permalink to &quot;5. ストレージレイヤー (`settings/db/`)&quot;">​</a></h3><ul><li><strong>Room Database (<code>IllustiaDatabase</code>)</strong>: ログインアカウント (<code>AccountEntity</code>)、履歴、保存済み作品データを保存。</li><li><strong>DataStore (<code>SettingsStore</code>)</strong>: アプリの個人設定項目 (<code>AppSettings</code>) をキー・バリュー形式で管理。</li></ul>',17)])])}const m=a(o,[["render",t]]);export{h as __pageData,m as default};
